class Solution {
  public String splitLoopedString(String[] strs) {
    int n = strs.length;
    // every string other than the cut one is placed in its larger orientation
    for (int i = 0; i < n; i++) {
      String rev = new StringBuilder(strs[i]).reverse().toString();
      if (rev.compareTo(strs[i]) > 0) strs[i] = rev;
    }
    String best = "";
    for (int i = 0; i < n; i++) {
      StringBuilder rest = new StringBuilder();
      for (int j = i + 1; j < n; j++) rest.append(strs[j]);
      for (int j = 0; j < i; j++) rest.append(strs[j]);
      String others = rest.toString();
      for (String s : new String[] {strs[i], new StringBuilder(strs[i]).reverse().toString()}) {
        for (int k = 0; k < s.length(); k++) {
          String cand = s.substring(k) + others + s.substring(0, k);
          if (cand.compareTo(best) > 0) best = cand;
        }
      }
    }
    return best;
  }
}
